// UNVERIFIED IN EDITOR
using System;
using System.IO;
using UnityEditor;
using UnityEngine;

namespace PatientZero.Environment.Editor
{
    /// <summary>Same-seat editor helper. All meshes/materials are generated by Unity, never handwritten assets.</summary>
    public static class WardPrimitives
    {
        public static Material Material(string name, Color colour)
        {
            const string folder = "Assets/PatientZero/Environment/Generated";
            Directory.CreateDirectory(Path.Combine(Application.dataPath, "PatientZero/Environment/Generated"));
            string path = folder + "/" + name + ".mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (!material)
            {
                var shader = Shader.Find("Universal Render Pipeline/Lit"); if (!shader) shader = Shader.Find("Standard");
                if (!shader) throw new InvalidOperationException("A supported render pipeline shader is required");
                material = new Material(shader); AssetDatabase.CreateAsset(material, path);
            }
            material.color = colour; return material;
        }
        public static GameObject Box(Transform parent, string name, Vector3 position, Vector3 size, Material material, bool collider = true)
        {
            var go = GameObject.CreatePrimitive(PrimitiveType.Cube); go.name = name; go.transform.SetParent(parent, false);
            go.transform.position = position; go.transform.localScale = size;
            go.GetComponent<Renderer>().sharedMaterial = material;
            if (!collider) UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());
            return go;
        }
        public static T FindInScene<T>(Transform root) where T : Component
        {
            T found = null;
            foreach (var sceneRoot in root.gameObject.scene.GetRootGameObjects())
                foreach (var item in sceneRoot.GetComponentsInChildren<T>(true))
                { if (found) throw new InvalidOperationException("Duplicate scene component: " + typeof(T).Name); found = item; }
            return found;
        }
        public static Transform Marker(Transform root, PatientZero.Core.LayoutPoint point)
        {
            var go = new GameObject(point.Id); go.transform.SetParent(root, false); go.transform.position = point.Position;
            go.AddComponent<PatientZero.Core.LayoutTag>().LayoutId = point.Id; return go.transform;
        }
    }
}
